Unit Test Code:
#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_calculate_wt_ct_already_calculated(void) {
    // Setup: Build a process queue where CT is already non-zero (so calculate_ct is NOT called)
    // Path condition: ptr->CT != 0
    // We need to insert processes, then call calculate_ct first to populate CT and TAT.
    // Then call calculate_wt, which should skip the if block and compute WT = TAT - BT.

    node *root = NULL;

    // Insert processes (IDs, AT, BT, priority)
    insert(&root, 1, 0, 5, 1);
    insert(&root, 2, 1, 4, 2);
    insert(&root, 3, 2, 3, 3);

    // First, calculate completion times to set CT and TAT (makes CT != 0)
    float avgCT = calculate_ct(&root);
    (void)avgCT; // unused, but needed to populate fields

    // Now CT fields are non-zero, TAT fields are set.
    // Verify that the first node's CT is not zero.
    TEST_ASSERT_NOT_EQUAL_INT(0, root->CT);

    // Test: call calculate_wt, which should take path 2 (skip calculate_ct)
    float avgWT = calculate_wt(&root);

    // Expected WT calculation: WT = TAT - BT for each node.
    // We can compute expected average manually.
    // Process 1: AT=0, BT=5 -> CT = 5 (assuming FCFS), TAT = CT - AT = 5, WT = TAT - BT = 0
    // Process 2: AT=1, BT=4 -> CT = 9, TAT = 8, WT = 4
    // Process 3: AT=2, BT=3 -> CT = 12, TAT = 10, WT = 7
    // Sum WT = 0 + 4 + 7 = 11, n = 3, avg = 11.0 / 3.0 ≈ 3.6666667
    float expected_avg = 11.0f / 3.0f;
    TEST_ASSERT_FLOAT_WITHIN(0.0001f, expected_avg, avgWT);

    // Additionally, verify WT fields were updated.
    node *ptr = root;
    int sum = 0;
    while (ptr != NULL) {
        TEST_ASSERT_EQUAL_INT(ptr->TAT - ptr->BT, ptr->WT);
        sum += ptr->WT;
        ptr = ptr->next;
    }
    TEST_ASSERT_EQUAL_INT(11, sum);

    // Cleanup
    helper_cleanup_process_queue(&root);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_calculate_wt_ct_already_calculated);
    return UNITY_END();
}

